      const name = field && field.serviceNowName ? field.serviceNowName : key;
      const hits = context && context.rootEl === rootEl
        ? (context.byName.get(name) || [])
        : deepQueryAll(rootEl, `[name="${field.escapedHint || field.escapedKey}"]`);
