          if (!hit || !hit.value) continue;
          if (looksLikeOwnLabel(field, hit.value)) continue;
          log.debug(`found ${key} via body fallback ${hit.source}`);
          return { key, found: true, value: hit.value, source: `body-fallback:${hit.source}` };
